/* What the UI knows about every screen key (title, code, and whether it is a drawn yard / shop map). Generated by tools/build-screens.mjs. */
import screenIndex from "./screenIndex.json";

export type ScreenInfo = { title: string; code?: string; missing?: boolean; alias?: string; map?: { yard: string; shop: boolean } };
export const KNOWN = screenIndex as Record<string, ScreenInfo>;
export const mapOf = (key: string) => KNOWN[key]?.map;
/** the key whose layout to load (a code with no source screen uses the reference's stand-in form) */
export const layoutKey = (key: string) => KNOWN[key]?.alias || key;
